function groupBy(list, keyFn) {
  var groups = {};
  list.forEach(function (item) {
    var key = keyFn(item);
    if (!groups[key]) {
      groups[key] = [];
    }
    groups[key].push(item);
  });
  return groups;
}

var words = ["apple", "bat", "cat", "dragon", "eel"];
console.log(groupBy(words, function (w) {
  return w.length;
}));
